// the raw position that stores the target (the middle of its band), or the nearest stored value's
inline unsigned raw_for(const uint8_t *table, int target) {
    int best = 0, bestd = 1 << 30, lo = -1, hi = -1;
    for (int r = 0; r < 254; r++) { const int d = table[r] > target ? table[r] - target : target - table[r]; if (d < bestd) { bestd = d; best = r; lo = hi = r; } else if (d == bestd && table[r] == table[best]) hi = r; }
    return unsigned((lo + hi) / 2);
}
